"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import { PauseIcon, PlayIcon } from "@hugeicons/core-free-icons";
import { IsoFigure, Line, Solid } from "@/components/anatomy/react/draw";
import { asksForStillness, follow, useInView, useStillness } from "@/components/anatomy/react/live";
import { translateAlong } from "@/components/anatomy/iso-kit";
import { LiveSolid, type SolidHandle } from "@/components/anatomy/live-solid";
import {
  BACK_LINES,
  BACK_PARTS,
  CARRIAGE_LINES,
  CARRIAGE_PARTS,
  CARRIED_LINES,
  CARRIED_PARTS,
  CONSOLE_LINES,
  CONSOLE_PARTS,
  FAR_PRONG,
  FRONT_LINES,
  GLASS_LINES,
  HALO,
  HEAD_PARTS,
  HEIGHT,
  KNOB_PARTS,
  NEAR_PRONG,
  P,
  PICK_LINES,
  PICK_PARTS,
  STILL_AT,
  TOP_LINES,
  TOP_PARTS,
  WIDTH,
  cableShape,
  clockFor,
  encoderTicks,
  knobAt,
  pickOpacity,
  poseAt,
  prongPaths,
  stateText,
  stickShape,
  tourAt,
} from "./claw-machine";
import "./the-claw-machine.css";

const MOST_DT = 1 / 30;
const SEEK = 0.16; // seconds for the claw to answer a reader's hand

const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x);

const SAYS =
  "An arcade claw machine in isometric view, its case glazed: the gantry runs the rail, the claw drops on its cable, closes on a capsule, lifts it clear of the pile and carries it to the chute";

/**
 * A still frame to check the drawing by: `?pose=0` holds the claw home, `?pose=1`
 * at the end of the cycle, anything between scrubs to there. Development only.
 */
function posedFromQuery(): number | null {
  if (!import.meta.env.DEV || typeof window === "undefined") return null;
  const raw = new URLSearchParams(window.location.search).get("pose");
  if (raw === null) return null;
  const value = Number(raw);
  return Number.isFinite(value) ? clamp01(value) : null;
}

export interface TheClawMachineProps {
  /** Dark or light drawing. The figure carries its own theme scope. */
  theme?: "dark" | "light";
  className?: string;
  /** Controlled play state. Leave undefined to let the figure own it. */
  playing?: boolean;
  /** Where an uncontrolled figure starts. Defaults to playing. */
  defaultPlaying?: boolean;
  onPlayingChange?: (playing: boolean) => void;
}

export function TheClawMachine({ theme = "dark", className, playing: controlled, defaultPlaying = true, onPlayingChange }: TheClawMachineProps) {
  const posed = React.useMemo(posedFromQuery, []);
  const posedRef = React.useRef(posed);
  posedRef.current = posed;

  const [own, setOwn] = React.useState(defaultPlaying);
  const playing = posed === null ? (controlled ?? own) : false;
  const setPlaying = React.useCallback(
    (next: boolean) => {
      if (controlled === undefined) setOwn(next);
      onPlayingChange?.(next);
    },
    [controlled, onPlayingChange],
  );

  const root = React.useRef<HTMLDivElement | null>(null);
  const inView = useInView(root);

  /* the three things that ride a translation, and the four that are rewritten in
     place every frame. Everything else is settled at load. */
  const carriage = React.useRef<SVGGElement | null>(null);
  const claw = React.useRef<SVGGElement | null>(null);
  const knob = React.useRef<SVGGElement | null>(null);
  const prize = React.useRef<SVGGElement | null>(null);
  const pick = React.useRef<SVGGElement | null>(null);
  const ticks = React.useRef<SVGPathElement | null>(null);
  const cable = React.useRef<SolidHandle | null>(null);
  const stick = React.useRef<SolidHandle | null>(null);
  const prongs = React.useMemo(() => Array.from({ length: FAR_PRONG + NEAR_PRONG }, () => React.createRef<SolidHandle>()), []);

  const frame = React.useRef(0);
  const last = React.useRef(0);
  const grab = React.useRef(0);
  const playRef = React.useRef(playing);
  const [pressing, setPressing] = React.useState(false);

  const started = posed ?? STILL_AT;
  const state = React.useRef({ clock: clockFor(started), at: started, want: started });

  const paint = React.useCallback(() => {
    const s = state.current;
    const pose = poseAt(s.at);

    carriage.current?.setAttribute("transform", translateAlong(P, [pose.x, 0, 0]));
    claw.current?.setAttribute("transform", translateAlong(P, [pose.x, 0, pose.hub]));

    const shapes = prongPaths(pose.hub, pose.shut);
    for (let index = 0; index < shapes.length; index++) prongs[index]?.current?.apply(shapes[index]!);
    cable.current?.apply(cableShape(pose.hub));

    if (ticks.current) {
      const d = encoderTicks(pose.hub);
      if (ticks.current.getAttribute("d") !== d) ticks.current.setAttribute("d", d);
    }

    stick.current?.apply(stickShape(pose.steer));
    knob.current?.setAttribute("transform", translateAlong(P, knobAt(pose.steer)));

    if (prize.current) {
      prize.current.setAttribute("transform", translateAlong(P, [pose.prize.x, 0, pose.prize.z]));
      prize.current.style.opacity = pose.prize.alpha.toFixed(3);
    }
    if (pick.current) pick.current.style.opacity = pickOpacity(s.at).toFixed(3);

    const host = root.current;
    if (host) {
      // the value the reader set, and the movement the claw is making on its way
      // there: both change on their own, so both are written from the one string
      const now = String(Math.round(clamp01(s.want) * 100));
      const said = `${stateText(s.want)} — ${now} per cent through the cycle`;
      if (host.getAttribute("aria-valuetext") !== said) {
        host.setAttribute("aria-valuenow", now);
        host.setAttribute("aria-valuetext", said);
      }
    }
  }, [prongs]);

  const stop = React.useCallback(() => {
    cancelAnimationFrame(frame.current);
    frame.current = 0;
  }, []);

  const run = React.useCallback(() => {
    if (frame.current) return;
    last.current = 0;
    const step = (now: number) => {
      const dt = last.current ? Math.min((now - last.current) / 1000, MOST_DT) : 1 / 60;
      last.current = now;
      const calm = asksForStillness();
      const s = state.current;
      const still = posedRef.current;
      if (still !== null) {
        s.at = still;
        s.want = still;
      } else if (playRef.current && !calm) {
        s.clock += dt;
        s.at = tourAt(s.clock);
        s.want = s.at;
      } else {
        s.at = calm ? s.want : follow(s.at, s.want, dt, SEEK);
      }
      paint();
      const settled = Math.abs(s.at - s.want) < 1e-3;
      frame.current = still !== null || (playRef.current && !calm) || (!calm && !settled) ? requestAnimationFrame(step) : 0;
    };
    frame.current = requestAnimationFrame(step);
  }, [paint]);

  React.useEffect(() => {
    if (inView) run();
    else stop();
  }, [inView, run, stop]);

  React.useEffect(() => {
    playRef.current = playing;
    if (posedRef.current !== null) return;
    const s = state.current;
    if (playing) {
      // pick the cycle up where the claw was left standing
      s.clock = clockFor(s.at);
    } else {
      // put it down where it stands, and let the reader take it from there
      s.want = s.at;
    }
    if (playing || inView) run();
  }, [playing, inView, run]);

  React.useEffect(() => () => stop(), [stop]);
  React.useEffect(() => paint(), [paint]);

  /* reduced motion: hold the frame the drawing is about — the claw just clear of
     the pile with the right one in it — and let the reader take it from there */
  const stillness = useStillness();
  React.useEffect(() => {
    if (!stillness || posedRef.current !== null) return;
    const s = state.current;
    s.at = STILL_AT;
    s.want = STILL_AT;
    paint();
  }, [stillness, paint]);

  /** the pointer reads across the frame: nought at the left, one at the right */
  const valueAt = (clientX: number) => {
    const box = root.current?.getBoundingClientRect();
    if (!box || !box.width) return null;
    return clamp01((clientX - (box.left + box.width * 0.1)) / (box.width * 0.8));
  };

  const seekTo = React.useCallback(
    (at: number) => {
      state.current.want = clamp01(at);
      run();
    },
    [run],
  );

  const opening = React.useMemo(() => poseAt(posed ?? STILL_AT), [posed]);
  const firstProngs = React.useMemo(() => prongPaths(opening.hub, opening.shut), [opening]);

  return (
    <div className={className ? `iso the-claw-machine ${className}` : "iso the-claw-machine"} data-theme={theme}>
      <div className="the-claw-machine-plate">
        <div
          ref={root}
          className="the-claw-machine-stage"
          role="slider"
          tabIndex={playing ? -1 : 0}
          data-interactive={playing ? undefined : ""}
          aria-label={SAYS}
          aria-readonly={playing}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round(STILL_AT * 100)}
          aria-valuetext={`lifting — ${Math.round(STILL_AT * 100)} per cent through the cycle`}
          style={{ touchAction: "pan-y" }}
          onPointerDown={(event) => {
            if (playing) return;
            const at = valueAt(event.clientX);
            if (at === null) return;
            event.currentTarget.setPointerCapture(event.pointerId);
            // hold the claw where it stands rather than throwing it at the pointer
            grab.current = state.current.want - at;
            setPressing(true);
            seekTo(at + grab.current);
          }}
          onPointerMove={(event) => {
            if (playing || !pressing) return;
            const at = valueAt(event.clientX);
            if (at === null) return;
            seekTo(at + grab.current);
          }}
          onPointerUp={(event) => {
            if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
            setPressing(false);
          }}
          onPointerCancel={() => setPressing(false)}
          onKeyDown={(event) => {
            if (playing) return;
            const step = event.shiftKey ? 0.1 : 0.03;
            let next: number | null = null;
            if (event.key === "ArrowLeft" || event.key === "ArrowDown") next = state.current.want - step;
            else if (event.key === "ArrowRight" || event.key === "ArrowUp") next = state.current.want + step;
            else if (event.key === "Home") next = 0;
            else if (event.key === "End") next = 1;
            if (next === null) return;
            event.preventDefault();
            seekTo(next);
          }}
        >
          <IsoFigure width={WIDTH} height={HEIGHT} className="the-claw-machine-figure" label={SAYS}>
            <path className="iso-halo" d={HALO} />

            {/* everything the glass is in front of: the cabinet, its doors, the
                deck, the chute down in the box, the case's solid back and side,
                the masts, the gantry, and the pile on the floor */}
            {BACK_PARTS.map((item, index) => (
              <Solid key={`back${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} halo={item.halo} className={item.mark} />
            ))}
            {BACK_LINES.map((item, index) => (
              <Line key={`backink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}

            {/* the carriage and its encoder, and the far prong: all three ride one
                translation, so the claw's travel is one transform and not many */}
            <g ref={carriage}>
              {CARRIAGE_PARTS.map((item, index) => (
                <Solid key={`car${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} className={item.mark} />
              ))}
              {CARRIAGE_LINES.map((item, index) => (
                <Line key={`carink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
              ))}
              <path ref={ticks} className="iso-line" data-tone="faint" d={encoderTicks(opening.hub)} />
              {firstProngs.slice(0, FAR_PRONG).map((paths, index) => (
                <LiveSolid key={`far${index}`} paths={paths} handle={prongs[index]} tone="hi" crease="faint" />
              ))}
            </g>

            {/* the pick, lying in the pile until the claw has it, and quiet again
                by the time the tour comes round */}
            <g ref={pick} style={{ opacity: pickOpacity(STILL_AT) }}>
              {PICK_PARTS.map((item, index) => (
                <Solid key={`pick${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} halo={item.halo} className={item.mark} />
              ))}
              {PICK_LINES.map((item, index) => (
                <Line key={`pickink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
              ))}
            </g>

            <LiveSolid paths={cableShape(opening.hub)} handle={cable} tone="lo" crease="faint" />

            {/* the prize: the same capsule as the pile's, in the claw's hold */}
            <g ref={prize} style={{ opacity: opening.prize.alpha }}>
              {CARRIED_PARTS.map((item, index) => (
                <Solid key={`prize${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} halo={item.halo} />
              ))}
              {CARRIED_LINES.map((item, index) => (
                <Line key={`prizeink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
              ))}
            </g>

            {/* the claw head, which carries the near two prongs with it */}
            <g ref={claw}>
              {HEAD_PARTS.map((item, index) => (
                <Solid key={`head${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} className={item.mark} />
              ))}
              {firstProngs.slice(FAR_PRONG, FAR_PRONG + NEAR_PRONG).map((paths, index) => (
                <LiveSolid key={`near${index}`} paths={paths} handle={prongs[FAR_PRONG + index]} tone="hi" crease="faint" />
              ))}
            </g>

            {/* the glass, drawn as its rim and the light it catches: no fill, so
                what is behind it stays what is read */}
            {GLASS_LINES.map((item, index) => (
              <Line key={`glass${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}

            {/* and the console, which is in front of the glass and holds the stick */}
            {CONSOLE_PARTS.map((item, index) => (
              <Solid key={`con${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} className={item.mark} />
            ))}
            {CONSOLE_LINES.map((item, index) => (
              <Line key={`conink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}
            <LiveSolid paths={stickShape(opening.steer)} handle={stick} tone="lo" crease="faint" />
            <g ref={knob}>
              {KNOB_PARTS.map((item, index) => (
                <Solid key={`knob${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} className={item.mark} />
              ))}
            </g>

            {TOP_PARTS.map((item, index) => (
              <Solid key={`top${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} className={item.mark} />
            ))}
            {TOP_LINES.map((item, index) => (
              <Line key={`topink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}
            {FRONT_LINES.map((item, index) => (
              <Line key={`frontink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}
          </IsoFigure>
        </div>

        <button
          type="button"
          className="the-claw-machine-control"
          aria-label={playing ? "Pause the run and take the claw" : "Play the run"}
          title={playing ? "Pause" : "Play"}
          onClick={() => setPlaying(!playing)}
        >
          <span className="the-claw-machine-swap" aria-hidden="true">
            <HugeiconsIcon className="the-claw-machine-glyph" data-on={playing ? "" : undefined} icon={PauseIcon} size={16} strokeWidth={1.6} />
            <HugeiconsIcon className="the-claw-machine-glyph" data-on={playing ? undefined : ""} icon={PlayIcon} size={16} strokeWidth={1.6} />
          </span>
        </button>
      </div>
    </div>
  );
}

/* The Claw Machine — an arcade machine with its case glazed. A gantry rail
   crosses the case, the carriage runs it, the claw lowers on its cable, shuts on
   one capsule, lifts it clear of the pile and carries it to the chute, where it
   lets go and the prize drops out of sight.

   One number drives the lot: how far through the cycle the machine is. The
   carriage's x, the length of cable paid out, the angle of the three prongs and
   the capsule riding in them are all that same number read six ways.

   Nothing is cut away. The case is glass, so the machine inside it is meant to
   be seen — the panes are drawn as the thing they are, their rim and the light
   they catch, and the frame around them is solid. The cabinet is a hollow shell
   of real walls with the chute sunk into it, and two masts carry the gantry the
   way the real ones do.

   Every number below is a world unit: x across the case, y through it, z up. */

import {
  cameraOf,
  circleRing,
  corners,
  cylinder,
  fitProjection,
  insetPlan,
  iso,
  lineOnTop,
  pathOf,
  planOutline,
  ringSeam,
  sideRing,
  sideSeam,
  sideTicks,
  slabOf,
  towardViewer,
  type Flat,
  type LineTone,
  type Plan,
  type Plane,
  type Point3,
  type Projection,
  type SolidPaths,
  type Tone,
} from "@/components/anatomy/iso-kit";
import { add3, circleSection, cross3, frameAlong, prismOf, rectSection, scale3, unit3 } from "@/components/anatomy/axis-parts";

export const WIDTH = 580;
const PAD = 20;

const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x);
const smooth01 = (x: number) => {
  const t = clamp01(x);
  return t * t * (3 - 2 * t);
};
/** an ease that runs past its mark and settles onto it: the carriage pulling up
    over the pick it has been sent for */
const easeBack = (x: number) => {
  const t = clamp01(x);
  const c1 = 1.24;
  return 1 + (c1 + 1) * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
};
const easeInOut = (x: number) => {
  const t = clamp01(x);
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
};

/* ——— the cabinet ———
   Wide enough that the pile has room to scatter, and no wider: the case and the
   load in it are the subject, not the box they stand in. */
export const HALF_X = 86;
const FACE_Y = 60; // the cabinet's near face, the one the reader reads
const BASE_Z0 = 16;
const BASE_Z1 = 74;
const DECK_Z0 = 74;
const DECK_Z1 = 82;
/** the case floor, which is the top of the deck */
export const FLOOR_Z = DECK_Z1;
const CASE_Y0 = -58;
const CASE_Y1 = 36;
const CASE_Z1 = 228;
const WALL = 8; // the thickness of the shell and of the case's frame
const TOP_Z0 = 228;
const TOP_Z1 = 246;

/* ——— the chute: a real well sunk in the cabinet, front left ——— */
export const CH_X0 = -54;
export const CH_X1 = -32;
const CH_Y0 = -14; // deep enough that a capsule dropped down the hole clears its rim
const CH_Y1 = 26;
const CH_BOTTOM = 36;

/* ——— the gantry: two flat rails on a pair of masts ——— */
const MAST_X0 = 72;
const RAIL_Y = 21; // the rails sit either side of the centre line
const RAIL_HALF = 5;
const RAIL_Z0 = 184;
const RAIL_Z1 = 192;
const RAIL_X = 78; // they run into the masts and stop on the posts
const BELT_HALF = 4.5;

/* ——— the carriage ——— */
const CAR_HALF = 22;
const CAR_Y = 16;
const CAR_Z0 = 200;
const CAR_Z1 = 214;
const TRUCK_HALF = 14;
const GLAND_Z0 = 194;
const GLAND_Z1 = 200;

/* ——— the claw: a yoke on the cable, and three prongs on its rim ———
   A prong is its pivot on the yoke, an elbow swung out from it and a finger
   turned back in, so shutting the jaws both closes and curls them. */
export const CAP_R = 10;
const YOKE_R = 15;
const COLLAR_Z1 = 6;
const GRIP = 31; // the capsule's centre sits this far under the yoke

/* ——— the run the machine makes ——— */
export const HOME_X = 46;
export const PICK_X = 0;
export const CHUTE_X = -43;
const HUB_UP = 168;
const HUB_DOWN = FLOOR_Z + CAP_R + GRIP;

/* ——— the phase, in six movements ——— */
const LINE_UP = 0.18; // the gantry runs out to the pick
const DROP = 0.34; // the cable pays out
const SHUT = 0.44; // the prongs close
const LIFT = 0.6; // and lift the prize clear
const CARRY = 0.78; // the gantry runs back to the chute
const OPEN = 0.9; // the prongs let go, and the prize is gone
const CYCLE = 15;
const DWELL = 2.4;
export const PERIOD = CYCLE + DWELL;

/* ——— what a drawing is made of ——— */
export interface Part {
  paths: SolidPaths;
  tone: Tone;
  crease: Tone | "none";
  lit: boolean;
  mark?: string;
  halo?: boolean;
}
export interface Ink {
  d: string;
  tone: LineTone;
  className?: string;
  free?: boolean | "start" | "end";
}
const part = (paths: SolidPaths, tone: Tone = "mid", crease: Tone | "none" = "faint", lit = false, mark?: string, halo = false): Part => ({ paths, tone, crease, lit, mark, halo });
const ink = (d: string, tone: LineTone = "lo", extra: { className?: string; free?: boolean | "start" | "end" } = {}): Ink => ({ d, tone, ...extra });

/** an axis-aligned block between two corners, creased on the edges of its faces */
function blockAt(x0: number, x1: number, y0: number, y1: number, z0: number, z1: number): SolidPaths {
  const frame = frameAlong([(x0 + x1) / 2, y0, (z0 + z1) / 2], [(x0 + x1) / 2, y1, (z0 + z1) / 2]);
  return prismOf(frame, rectSection(x1 - x0, z1 - z0), 0, y1 - y0, P, { creases: true });
}
/** a round bar between two points: how every rail, pin and can is drawn */
const pipe = (from: Point3, to: Point3, radius: number, steps = 12) =>
  prismOf(frameAlong(from, to), circleSection(radius, steps), 0, Math.hypot(to[0] - from[0], to[1] - from[1], to[2] - from[2]), P, { creases: false });

/** a line ruled on the cabinet's near face (a constant y) */
const onFaceY = (y: number, points: Plane[]) => pathOf(points.map(([x, z]) => iso([x, y, z], P)), false);
/** and one on a flank (a constant x) */
const onSideX = (x: number, points: Plane[]) => pathOf(points.map(([y, z]) => iso([x, y, z], P)), false);

/** a flat strap between two points, its width in the plane it swings in and its
    thickness across that plane */
function strap(from: Point3, to: Point3, width: number, thick: number, across: Point3): SolidPaths {
  const span: Point3 = [to[0] - from[0], to[1] - from[1], to[2] - from[2]];
  const length = Math.hypot(span[0], span[1], span[2]) || 1;
  const a: Point3 = [span[0] / length, span[1] / length, span[2] / length];
  const along = across[0] * a[0] + across[1] * a[1] + across[2] * a[2];
  const v = unit3([across[0] - a[0] * along, across[1] - a[1] * along, across[2] - a[2] * along]);
  const u = cross3(a, v);
  return prismOf({ o: from, a, u, v }, rectSection(width, thick), 0, length, P, { creases: true });
}

/* ——— the capsule: a ball, cut into slices so the shading follows its curve ———
   A stack of discs is how the kit draws anything round, and left alone it shows
   every join. So each slice is a true ring, wide at the bottom and narrow at the
   top, and the whole ball carries one outline: the silhouette of the lot. The
   tone steps inside it are the only thing the eye is meant to see. */
const CAP_E = [-0.999, -0.925, -0.835, -0.71, -0.57, -0.39, 0, 0.39, 0.57, 0.71, 0.835, 0.925, 0.999];
const CAP_STEPS = 14;
const capRadius = (e: number) => CAP_R * Math.sqrt(Math.max(1 - e * e, 0.002));

/** the convex rim round a cloud of points: the ball's one outline */
function rimOf(points: Flat[]): Flat[] {
  const sorted = [...points].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const turn = (o: Flat, a: Flat, b: Flat) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const walk = (list: Flat[]) => {
    const out: Flat[] = [];
    for (const point of list) {
      while (out.length >= 2 && turn(out[out.length - 2]!, out[out.length - 1]!, point) <= 0) out.pop();
      out.push(point);
    }
    return out;
  };
  return [...walk(sorted).slice(0, -1), ...walk([...sorted].reverse()).slice(0, -1)];
}

/** one slice of the ball, shaded like a slab: its tone is the way its side faces
    the azimuthal light, so two rings stacked read as one turning surface */
function ballSlice(x: number, y: number, r0: number, z0: number, r1: number, z1: number, shades: string[][], cloud: Flat[]): Flat[] {
  const { sinA, cosA } = cameraOf(P);
  const [lx, ly] = [-sinA, cosA];
  const [vx, vy] = towardViewer(P);
  const low: Flat[] = [];
  const high: Flat[] = [];
  for (let step = 0; step < CAP_STEPS; step++) {
    const angle = (step / CAP_STEPS) * Math.PI * 2;
    const cos = Math.cos(angle);
    const sin = Math.sin(angle);
    low.push(iso([x + r0 * cos, y + r0 * sin, z0], P));
    high.push(iso([x + r1 * cos, y + r1 * sin, z1], P));
    cloud.push(low[step]!, high[step]!);
  }
  for (let step = 0; step < CAP_STEPS; step++) {
    const next = (step + 1) % CAP_STEPS;
    const [ax, ay] = [low[step]!, low[next]!];
    const dx = ay[0] - ax[0];
    const dy = ay[1] - ax[1];
    const span = Math.hypot(dx, dy) || 1;
    const [nx, ny] = [dy / span, -dx / span];
    if (nx * vx + ny * vy <= 1e-9) continue;
    const shade = Math.min(3, Math.max(0, Math.floor(((nx * lx + ny * ly + 1) / 2) * 4)));
    shades[shade]!.push(pathOf([low[step]!, low[next]!, high[next]!, high[step]!], true));
  }
  return high;
}

export function capsuleParts(x: number, y: number, z: number, tone: Tone = "hi", crease: Tone | "none" = "faint"): Part[] {
  const shades: string[][] = [[], [], [], []];
  const cloud: Flat[] = [];
  let top = "";
  for (let band = 0; band < CAP_E.length - 1; band++) {
    const e0 = CAP_E[band]!;
    const e1 = CAP_E[band + 1]!;
    const high = ballSlice(x, y, capRadius(e0), z + CAP_R * e0, capRadius(e1), z + CAP_R * e1, shades, cloud);
    if (band === CAP_E.length - 2) top = pathOf(high, true);
  }
  const ball = pathOf(rimOf(cloud), true);
  return [part({ fill: ball, outline: ball, crease: "", top, shades: shades.map((list) => list.join("")), seamless: true }, tone, crease)];
}

/* ——— the pile: capsules loose on the floor, and two nestled on the back row ———
   The pick is the lit one and sits dead centre, with a clear ring round it so the
   prongs can come down. It is the same size and shape as every other, which is
   the point: the machine finds it by where it is, not by what it is. */
export const PILE: Point3[] = [
  [-46, -40, 0],
  [-16, -42, 0],
  [16, -42, 0],
  [44, -26, 0],
  [-56, -16, 0],
  [0, 0, 0],
  [46, 10, 0],
  [26, 18, 0],
  [-30, -14, 0],
  [-31, -41, 22],
  [-1, -42, 22],
];
export const PICK_INDEX = 5;
export const PICK = PILE[PICK_INDEX]!;

/* ——— the projection: fitted once, over the whole run ———
   The extremes are the cabinet, its marquee, the joystick at both ends of its
   lean and the claw at the top of its travel and at the bottom with the prongs
   wide, so nothing is ever clipped by the frame. */
function extremes(): Point3[] {
  const out: Point3[] = [];
  const body: Plan = { x: -HALF_X, y: -FACE_Y, w: HALF_X * 2, d: FACE_Y * 2 + 6, r: 0 };
  for (const [x, y] of corners(body, 0)) out.push([x, y, 0], [x, y, BASE_Z0], [x, y, CASE_Z1], [x, y, TOP_Z1]);
  for (const [x, y] of corners(insetPlan(body, 6), 0)) out.push([x, y, TOP_Z1]);
  for (const lean of [1, -1]) out.push([-40 + lean * 20, 44, 118], [-40 + lean * 20, 56, 88]);
  for (const x of [HOME_X, PICK_X, CHUTE_X]) {
    out.push([x + CAR_HALF, -CAR_Y, CAR_Z1], [x - CAR_HALF, CAR_Y, CAR_Z1], [x, ENCODER_Y, 208]);
    out.push([x, 0, HUB_UP + COLLAR_Z1 + 4]);
    for (const side of [-1, 1]) out.push([x + side * 30, 0, HUB_DOWN - 29], [x + side * 10, 0, HUB_DOWN - 31 - CAP_R], [x, 0, HUB_DOWN - 31 + CAP_R]);
  }
  return out;
}
const ENCODER_Y = 31;

const UNIT: Projection = { origin: [0, 0], scale: 1 };
const RAW = extremes().map((point) => iso(point, UNIT));
const SPAN_X = Math.max(...RAW.map(([x]) => x)) - Math.min(...RAW.map(([x]) => x));
const SPAN_Y = Math.max(...RAW.map(([, y]) => y)) - Math.min(...RAW.map(([, y]) => y));
/** the plate is cut to the drawing's own shape, so nothing is padded away */
export const HEIGHT = Math.round((WIDTH - PAD * 2) * (SPAN_Y / SPAN_X) + PAD * 2);
export const P: Projection = fitProjection(extremes(), WIDTH, HEIGHT, { pad: PAD });

